<script setup>
import {ref,onMounted,computed} from 'vue'
import {api,download,session} from '../services/api.js'
import GlassWindow from './GlassWindow.vue'
const canManage=computed(()=>['owner','admin'].includes(session.user?.role)),sources=ref([]),nodes=ref([]),credentials=ref([]),result=ref({items:[],total:0}),page=ref(1),q=ref(''),exporterId=ref(''),error=ref(''),message=ref(''),busy=ref(false),open=ref(false),editId=ref(null),details=ref(null)
const empty=()=>({name:'',nodeId:'',format:'ipfix-v10',sourceIp:'',tlsFingerprint:'',enabled:false}),form=ref(empty()),capture=ref(''),lines=ref(''),blob=ref({credentialId:'',account:'',container:'insights-logs-flowlogflowevent',blob:''})
const query=()=>new URLSearchParams({q:q.value,...(exporterId.value?{exporterId:exporterId.value}:{}),page:page.value,pageSize:25})
const selected=computed(()=>sources.value.find(s=>s.id===exporterId.value))
async function load(){busy.value=true;error.value='';try{result.value=await api('/telemetry/observations?'+query());if(canManage.value)sources.value=await api('/telemetry/exporters')}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';try{await api('/telemetry/exporters'+(editId.value?'/'+editId.value:''),{method:editId.value?'PUT':'POST',body:form.value});open.value=false;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function edit(source){editId.value=source?.id||null;form.value=source?{name:source.name,nodeId:source.node_id,format:source.format,sourceIp:source.source_ip||'',tlsFingerprint:source.tls_fingerprint||'',enabled:source.enabled}:empty();open.value=true}
async function importCapture(){busy.value=true;error.value='';try{const output=await api(`/telemetry/exporters/${exporterId.value}/`+(selected.value.format==='azure-vnet'?'vnet-blob':'syslog'),{method:'POST',body:selected.value.format==='azure-vnet'?blob.value:{captureKey:capture.value,lines:lines.value.split(/\r?\n/).filter(Boolean)}});message.value=`${output.accepted||0} observations imported · ${output.duplicates||0} duplicates`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportRows(){try{await download('/telemetry/observations/export?'+query(),'traffic-observations.json')}catch(e){error.value=e.message}}
onMounted(async()=>{await load();if(canManage.value)try{const [n,c]=await Promise.all([api('/nodes'),api('/credentials')]);nodes.value=n.items||n;credentials.value=(c.items||c).filter(c=>c.type==='azure')}catch(e){error.value=e.message}})
</script>
<template><section class="panel glass"><div class="panel-title"><h2>Traffic sources</h2><div class="actions"><button class="button secondary" @click="exportRows">Export</button><button v-if="canManage" class="button primary" @click="edit()">Add exporter</button></div></div><div class="body"><p class="muted">These are observations, not unique connection counts. Flow records do not prove a firewall verdict unless the source supplies one. Imported traffic also appears in Firewall Events, Mapping and Internet.</p><p v-if="error" class="error-msg" role="alert">{{error}}</p><p v-if="message" class="success-msg">{{message}}</p><form class="actions" @submit.prevent="page=1;load()"><input v-model="q" placeholder="Search endpoints or source" aria-label="Search traffic observations"><select v-model="exporterId" aria-label="Traffic source" @change="page=1;load()"><option value="">All sources</option><option v-for="s in sources" :key="s.id" :value="s.id">{{s.name}} · {{s.format}}</option></select><button class="button secondary" :disabled="busy">Search</button></form><template v-if="selected"><p>{{selected.accepted}} accepted · {{selected.rejected}} rejected · {{selected.duplicates}} duplicates · {{selected.missing_templates}} missing templates <button v-if="canManage" class="button small secondary" @click="edit(selected)">Edit source</button></p><p v-if="selected.last_error" class="error-msg">{{selected.last_error}}</p><details v-if="canManage&&selected.enabled&&!['ipfix-v10','netflow-v9'].includes(selected.format)"><summary>Import capture</summary><form class="import-form" @submit.prevent="importCapture"><template v-if="selected.format==='azure-vnet'"><label>Azure vault credential<select v-model="blob.credentialId" required><option value="">Select credential</option><option v-for="c in credentials" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Storage account<input v-model="blob.account" required></label><label>Container<input v-model="blob.container" required></label><label>Existing blob path<input v-model="blob.blob" required></label><p class="muted">Requires Storage Blob Data Reader. Reads this existing blob only; does not enable logging. Repeat reads use ETags and tuple checkpoints.</p></template><template v-else><label>Unique capture key<input v-model="capture" required maxlength="300"></label><label>Syslog records<textarea v-model="lines" rows="5" required></textarea></label></template><button class="button primary" :disabled="busy">Import</button></form></details></template><div class="table-wrap"><table><thead><tr><th>Observed</th><th>Source</th><th>Endpoints</th><th>Protocol / port</th><th>Verdict</th><th></th></tr></thead><tbody><tr v-for="r in result.items" :key="r.id"><td>{{new Date(r.observed_at).toLocaleString()}}</td><td>{{r.exporter_name}}</td><td>{{r.src_ip}} → {{r.dst_ip}}</td><td>{{r.protocol}} / {{r.dst_port??'—'}}</td><td>{{r.action||'Not supplied'}}</td><td><button class="button small secondary" @click="details=r">Evidence</button></td></tr><tr v-if="!result.items.length"><td colspan="6">{{busy?'Loading…':'No traffic observations.'}}</td></tr></tbody></table></div><div class="actions"><span>{{result.total}} observations · Page {{page}}</span><button class="button secondary" :disabled="page===1||busy" @click="page--;load()">Previous</button><button class="button secondary" :disabled="page*25>=result.total||busy" @click="page++;load()">Next</button></div></div><GlassWindow v-model="open" :title="editId?'Edit traffic exporter':'Add traffic exporter'"><form class="import-form" @submit.prevent="save"><p v-if="error" class="error-msg">{{error}}</p><label>Name<input v-model="form.name" required maxlength="120"></label><label>Collector asset<select v-model="form.nodeId" required :disabled="!!editId"><option value="">Select asset</option><option v-for="n in nodes" :key="n.id" :value="n.id">{{n.hostname}} · {{n.ip}}</option></select></label><label>Format<select v-model="form.format" :disabled="!!editId"><option v-for="f in ['ipfix-v10','netflow-v9','pf-filterlog','mikrotik-firewall','sonicwall-kv','azure-vnet']" :key="f">{{f}}</option></select></label><label>Exporter source IP<input v-model="form.sourceIp" placeholder="Required for live receivers"></label><label>TLS client certificate SHA-256 fingerprint<input v-model="form.tlsFingerprint" maxlength="64" placeholder="64 hexadecimal characters"></label><label class="switch-field"><span>Enabled</span><input v-model="form.enabled" type="checkbox" role="switch"><span class="switch-control" aria-hidden="true"></span></label><button class="button primary" :disabled="busy">Save exporter</button></form></GlassWindow><GlassWindow :model-value="!!details" title="Traffic evidence" @update:model-value="details=null"><pre>{{JSON.stringify(details?.metadata,null,2)}}</pre><a v-if="details?.event_id" :href="'/logs?event='+details.event_id">View event</a></GlassWindow></section></template>
<style scoped>.body{padding:16px;min-width:0}.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:14px 0}.actions input{flex:1;min-width:180px}.import-form{display:grid;gap:14px;padding:16px}.import-form label:not(.switch-field){display:grid;gap:6px}.table-wrap{max-width:100%;overflow:auto}table{width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%;padding:16px}</style>
